import re, sys

print("regex repl. type :pattern <re>, :text <str>, :run, :quit")
pattern, text = None, ""
while True:
    try: line = input("> ")
    except EOFError: break
    if line.startswith(":pattern "): pattern = line[9:]
    elif line.startswith(":text "): text = line[6:]
    elif line == ":quit": break
    elif line == ":run":
        if not pattern: print("no pattern"); continue
        try:
            r = re.compile(pattern)
            ms = list(r.finditer(text))
            print(f"{len(ms)} matches")
            for m in ms: print(f"  span={m.span()} groups={m.groups()} -> {m.group()!r}")
        except re.error as e: print(f"err: {e}")
    else: print("unknown cmd")
